from typing import Iterator, Tuple

def _iter_escaped_chars(addr: str) -> Iterator[Tuple[int, str]]:
    pos = 0
    escape = False
    for pos, ch in enumerate(addr):
        if escape:
            yield (pos, '\\' + ch)
            escape = False
        elif ch == '\\':
            escape = True
        else:
            yield (pos, ch)
    if escape:
